func TestClientStreamEnds(t *testing.T) {
	exp := tracetest.NewInMemoryExporter()
	tp := sdktrace.NewTracerProvider(sdktrace.WithSyncer(exp))
	prevProp := otel.GetTextMapPropagator()
	defer otel.SetTextMapPropagator(prevProp)
	otel.SetTextMapPropagator(propagation.TraceContext{})
	icpt := StreamClientInterceptor(WithTracerProvider(tp)) // global propagator
	start := func(desc *grpc.StreamDesc, fs *fakeStream, serr error) (grpc.ClientStream, error) {
		return icpt(context.Background(), desc, nil, "/pkg.Svc/M", func(ctx context.Context, _ *grpc.StreamDesc, _ *grpc.ClientConn, _ string, _ ...grpc.CallOption) (grpc.ClientStream, error) {
			md, _ := metadata.FromOutgoingContext(ctx)
			if len(md.Get("traceparent")) == 0 {
				t.Error("traceparent not injected")
			}
			if serr != nil {
				return nil, serr
			}
			return fs, nil
		})
	}
	// server streaming: ends on io.EOF
	cs, _ := start(&grpc.StreamDesc{ServerStreams: true}, &fakeStream{recv: []error{nil, io.EOF}}, nil)
	_ = cs.RecvMsg(nil)
	_ = cs.RecvMsg(nil)
	// client streaming: ends after the single response
	cs, _ = start(&grpc.StreamDesc{ClientStreams: true}, &fakeStream{recv: []error{nil}}, nil)
	if err := cs.SendMsg(nil); err != nil {
		t.Fatal(err)
	}
	_ = cs.RecvMsg(nil)
	// error on receive
	cs, _ = start(&grpc.StreamDesc{ServerStreams: true}, &fakeStream{recv: []error{status.Error(grpccodes.Internal, "x")}}, nil)
	_ = cs.RecvMsg(nil)
	// error on send (io.EOF on send is not an error by itself)
	fs := &fakeStream{send: io.EOF}
	cs, _ = start(&grpc.StreamDesc{ClientStreams: true}, fs, nil)
	_ = cs.SendMsg(nil)
	fs.send = errors.New("broken")
	_ = cs.SendMsg(nil)
	// streamer fails
	if _, err := start(&grpc.StreamDesc{}, nil, status.Error(grpccodes.Unavailable, "down")); err == nil {
		t.Fatal("streamer error swallowed")
	}

	deadline := time.Now().Add(5 * time.Second)
	for len(exp.GetSpans()) < 5 && time.Now().Before(deadline) {
		time.Sleep(5 * time.Millisecond)
	}
	var got []string
	for _, s := range exp.GetSpans() {
		got = append(got, s.Status.Code.String())
	}
	sort.Strings(got)
	if len(got) != 5 || got[0] != "Error" || got[1] != "Error" || got[2] != "Error" || got[3] != "Unset" || got[4] != "Unset" {
		t.Fatalf("statuses = %v", got)
	}
}

